files.content:
:root {
  --bg: #1d3557;
  --card: #f1faee;
  --ink: #1d3557;
  --muted: #457b9d;
  --accent: #e76f51;
  --accent-2: #2a9d8f;
  --cell: #ffffff;
  --cell-border: #d6e2e9;
  --radius: 14px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--ink);
  background: radial-gradient(circle at 20% 0%, #2a9d8f 0%, var(--bg) 55%, #14243a 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.card {
  width: 100%;
  max-width: 640px;
  background: var(--card);
  border-radius: var(--radius);
  padding: 28px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.35);
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.app-header h1 {
  margin: 0 0 6px;
  font-size: 1.75rem;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 1rem;
}

/* Palette */
.palette {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
}

.swatch {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 3px solid transparent;
  background: var(--swatch);
  cursor: pointer;
  padding: 0;
  transition: transform 0.12s ease, box-shadow 0.12s ease, border-color 0.12s ease;
}

.swatch:hover { transform: translateY(-2px); box-shadow: 0 6px 12px rgba(0,0,0,0.18); }
.swatch:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }
.swatch:active { transform: translateY(1px) scale(0.96); }
.swatch.is-selected { border-color: var(--ink); box-shadow: 0 0 0 3px rgba(29,53,87,0.15); }

.tool, .clear {
  font: inherit;
  font-size: 1rem;
  border-radius: 10px;
  border: 2px solid var(--muted);
  background: #fff;
  color: var(--ink);
  padding: 10px 16px;
  cursor: pointer;
  transition: background 0.12s ease, color 0.12s ease, transform 0.1s ease, box-shadow 0.12s ease;
}

.tool:hover, .clear:hover { background: var(--muted); color: #fff; box-shadow: 0 4px 10px rgba(0,0,0,0.15); }
.tool:focus-visible, .clear:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.tool:active, .clear:active { transform: scale(0.97); }

.tool[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

/* Board */
.board-wrap {
  display: flex;
  justify-content: center;
}

.grid {
  display: grid;
  grid-template-columns: repeat(16, 1fr);
  gap: 2px;
  width: 100%;
  max-width: 512px;
  aspect-ratio: 1 / 1;
  background: var(--cell-border);
  padding: 4px;
  border-radius: 10px;
}

.cell {
  border: none;
  padding: 0;
  background: var(--cell);
  border-radius: 3px;
  cursor: pointer;
  transition: transform 0.08s ease, box-shadow 0.08s ease;
  min-width: 0;
  min-height: 0;
}

.cell:hover { box-shadow: inset 0 0 0 2px var(--accent); }
.cell:focus-visible { outline: 2px solid var(--ink); outline-offset: -2px; z-index: 1; }
.cell:active { transform: scale(0.9); }

/* Footer */
.controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.count {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--ink);
}

.clear {
  border-color: var(--accent);
  color: var(--accent);
  font-weight: 600;
}

.clear:hover { background: var(--accent); color: #fff; }

@media (max-width: 420px) {
  .card { padding: 20px; gap: 18px; }
  .swatch { width: 38px; height: 38px; }
  .app-header h1 { font-size: 1.5rem; }
}

(function () {
  'use strict';

  var SIZE = 16;
  var grid = document.getElementById('grid');
  var countEl = document.getElementById('count');
  var eraserBtn = document.getElementById('eraser');
  var clearBtn = document.getElementById('clear');
  var swatches = Array.prototype.slice.call(document.querySelectorAll('.swatch'));

  var selectedColor = swatches[0].getAttribute('data-color');
  var eraserActive = false;
  var painted = new Set();

  // Build grid
  var cells = [];
  for (var i = 0; i < SIZE * SIZE; i++) {
    var cell = document.createElement('button');
    cell.type = 'button';
    cell.className = 'cell';
    cell.setAttribute('aria-label', 'Cell ' + (Math.floor(i / SIZE) + 1) + ', ' + ((i % SIZE) + 1));
    cell.dataset.index = String(i);
    cell.addEventListener('click', onCellClick);
    grid.appendChild(cell);
    cells.push(cell);
  }

  function updateCount() {
    countEl.textContent = 'Painted cells: ' + painted.size;
  }

  function paintCell(cell) {
    var idx = cell.dataset.index;
    if (eraserActive) {
      cell.style.background = '';
      painted.delete(idx);
    } else {
      cell.style.background = selectedColor;
      painted.add(idx);
    }
    updateCount();
  }

  function onCellClick(e) {
    paintCell(e.currentTarget);
  }

  // Palette selection
  swatches.forEach(function (btn) {
    btn.addEventListener('click', function () {
      selectedColor = btn.getAttribute('data-color');
      eraserActive = false;
      eraserBtn.setAttribute('aria-pressed', 'false');
      swatches.forEach(function (s) {
        var on = s === btn;
        s.classList.toggle('is-selected', on);
        s.setAttribute('aria-pressed', on ? 'true' : 'false');
      });
    });
  });

  // Eraser toggle
  eraserBtn.addEventListener('click', function () {
    eraserActive = !eraserActive;
    eraserBtn.setAttribute('aria-pressed', eraserActive ? 'true' : 'false');
    if (eraserActive) {
      swatches.forEach(function (s) {
        s.classList.remove('is-selected');
        s.setAttribute('aria-pressed', 'false');
      });
    } else {
      var first = swatches[0];
      selectedColor = first.getAttribute('data-color');
      first.classList.add('is-selected');
      first.setAttribute('aria-pressed', 'true');
    }
  });

  // Clear
  clearBtn.addEventListener('click', function () {
    cells.forEach(function (c) { c.style.background = ''; });
    painted.clear();
    updateCount();
  });

  updateCount();
})();
